def _k1_gemm(lhs: torch.Tensor, w0: torch.Tensor, w1: torch.Tensor) -> tuple[torch.Tensor, ...]:
    t, k = lhs.size()
    _, n = w0.size()
    out_matmul_77 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    out_matmul_76 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    for tile_t, tile_n in hl.tile([t, n]):
        acc_matmul_77 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        acc_matmul_76 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        for tile_k in hl.tile(k):
            xt = lhs[tile_t, tile_k]
            acc_matmul_77 = hl.dot(xt, w0[tile_k, tile_n], acc=acc_matmul_77)
            acc_matmul_76 = hl.dot(xt, w1[tile_k, tile_n], acc=acc_matmul_76)
        out_matmul_77[tile_t, tile_n] = acc_matmul_77
        out_matmul_76[tile_t, tile_n] = acc_matmul_76
    return out_matmul_77, out_matmul_76


